int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info) {
    struct hwsim_new_radio_params params = { };
    struct nlattr *attr;
    int err;

    attr = info->attrs[HWSIM_ATTR_REG_STRICT_REG];
    if (attr)
        params.reg_strict = nla_get_u8(attr);

    attr = info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE];
    if (attr)
        params.support_p2p_device = nla_get_u8(attr);

    attr = info->attrs[HWSIM_ATTR_NO_IR];
    if (attr)
        params.no_ir = nla_get_u8(attr);

    attr = info->attrs[HWSIM_ATTR_SKB_CB_PRESENT];
    if (attr)
        params.skb_cb_present = nla_get_u8(attr);

    attr = info->attrs[HWSIM_ATTR_RADIO_NAME];
    if (attr) {
        size_t len = strlen(nla_get_string(attr)) + 1;
        params.name = kmalloc(len, GFP_KERNEL);
        if (!params.name)
            return -ENOMEM;
        strcpy(params.name, nla_get_string(attr));
    }

    attr = info->attrs[HWSIM_ATTR_REGulatory_domain_idx];
    if (attr)
        params.regulatory_domain_idx = nla_get_u32(attr);

    err = mac80211_hwsim_new_radio(&params);
    if (err < 0)
        goto error;

    return 0;

error:
    kfree(params.name);
    return err;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info) {
    struct hwsim_new_radio_params params = { 0 };
    int err;

    if (info->attrs[HWSIM_ATTR_REG_STRICTNESS]) {
        params.reg_strictness = nla_get_u8(info->attrs[HWSIM_ATTR_REG_STRICTNESS]);
    }

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE]) {
        params.support_p2p_device = !!nla_get_u8(info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE]);
    }

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        params.channels = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNELS]);
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        params.radio_name = kstrdup(nla_get_string(info->attrs[HWSIM_ATTR_RADIO_NAME]), GFP_KERNEL);
        if (!params.radio_name) {
            return -ENOMEM;
        }
    }

    if (info->attrs[HWSIM_ATTR_CUSTOM_REG_DOMAIN]) {
        params.custom_reg_domain = nla_get_u32(info->attrs[HWSIM_ATTR_CUSTOM_REG_DOMAIN]);
        if (params.custom_reg_domain >= MAC80211_HWSIM_MAX_CUSTOM_REG_DOMAINS) {
            err = -EINVAL;
            goto free_name;
        }
    }

    err = mac80211_hwsim_new_radio(&params);
    if (err < 0) {
        goto free_name;
    }

free_name:
    kfree(params.radio_name);
    return err;
}

