int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info) {
    struct hwsim_new_radio_params params = {0};
    int err;

    if (info->attrs[HWSIM_ATTR_REG_STRICTNESS]) {
        params.reg_strictness = nla_get_u32(info->attrs[HWSIM_ATTR_REG_STRICTNESS]);
    }

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE])
        params.support_p2p_device = true;

    if (info->attrs[HWSIM_ATTR_CHANNELS])
        params.channels = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNELS]);

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        const char *name = nla_data(info->attrs[HWSIM_ATTR_RADIO_NAME]);
        params.radio_name = kstrdup(name, GFP_KERNEL);
        if (!params.radio_name)
            return -ENOMEM;
    }

    if (info->attrs[HWSIM_ATTR_REGulatory_DOMAIN_IDX]) {
        int idx = nla_get_u32(info->attrs[HWSIM_ATTR_REGULATORY_DOMAIN_IDX]);
        if (idx < 0 || idx >= MAX_REGULATORY_DOMAINS) {
            err = -EINVAL;
            goto free_name;
        }
        params.regulatory_domain_idx = idx;
    }

    err = mac80211_hwsim_new_radio(&params);
    if (err < 0)
        goto free_name;

    return 0;

free_name:
    kfree(params.radio_name);
    return err;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info)
{
    struct hwsim_new_radio_params params = { 0 };
    struct mac80211_hwsim *hwsim;
    int err;

    if (info->attrs[HWSIM_ATTR_REG_STRICT_REG])
        params.reg_strict = true;

    if (info->attrs[HWSIM_ATTR_SUPPORT_IBSS_RSN])
        params.support_ibss_rsn = true;

    if (info->attrs[HWSIM_ATTR_NO_VIF] &&
        nla_get_u8(info->attrs[HWSIM_ATTR_NO_VIF]))
        params.no_vif = true;

    if (info->attrs[HWSIM_ATTR_NO_CHAN_SWITCH] &&
        nla_get_u8(info->attrs[HWSIM_ATTR_NO_CHAN_SWITCH]))
        params.no_chan_switch = true;

    if (info->attrs[HWSIM_ATTR_NAME]) {
        params.name = nla_data(info->attrs[HWSIM_ATTR_NAME]);
        params.name_len = nla_len(info->attrs[HWSIM_ATTR_NAME]);
        params.name = kstrndup(params.name, params.name_len, GFP_KERNEL);
        if (!params.name)
            return -ENOMEM;
    }

    if (info->attrs[HWSIM_ATTR_REGulatory_DOMAIN] &&
        nla_get_u8(info->attrs[HWSIM_ATTR_REGulatory_DOMAIN])) {
        params.regulatory_domain = nla_get_u8(info->attrs[HWSIM_ATTR_REGulatory_DOMAIN]);
        if (params.regulatory_domain >= MAX_REGDOM)
            return -EINVAL;
    }

    hwsim = mac80211_hwsim_new_radio(&params);
    if (IS_ERR(hwsim)) {
        err = PTR_ERR(hwsim);
        kfree(params.name);
        return err;
    }

    kfree(params.name);
    return 0;
}
